import{t as e}from"./rolldown-runtime.Co4_kzzg.mjs";import{C as t,P as n,l as r,s as i,u as a}from"./react.DRsw1btq.mjs";import{S as o,t as s}from"./motion.BvrNwy9e.mjs";import{Y as c,g as l,n as u}from"./framer.C79NkfeI.mjs";import{n as d,t as f}from"./YouTube.DL0EjL28.mjs";var p,m,h,g,_;e((()=>{i(),c(),s(),t(),d(),p=a(n,{children:[r(`p`,{children:r(`em`,{children:`What is this? Inspired by other leaders in design and engineering, I revisit my very own readme every few years. I share it to help people get to know me and how I work, hoping it inspires others to write one for themselves and their team.`})}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Welcome`}),r(`p`,{children:`Welcome to the team. As a leader, my mission is simple: create the conditions for great work to happen. I want you to do work you’re proud of most days—because, let’s face it, not every day will be perfect. I do this by understanding what drives you, challenging our thinking, and providing clear context and vision. Along the way, I focus on building and growing a team of exceptional talent.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`To work well together, we need to define our relationship. Below is a quick guide to how I operate: what you can expect from me, my principles, and, yes, some of my quirks. It’s meant to help us hit the ground running—but it’s no substitute for building a real connection.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Work Mode`}),r(`img`,{alt:`Workplace setting`,className:`framer-image`,height:`427`,src:`https://framerusercontent.com/images/4KHjFzzCe4x4HCsHdmyP18pI0.jpg`,srcSet:`https://framerusercontent.com/images/4KHjFzzCe4x4HCsHdmyP18pI0.jpg?scale-down-to=512 512w,https://framerusercontent.com/images/4KHjFzzCe4x4HCsHdmyP18pI0.jpg?scale-down-to=1024 1024w,https://framerusercontent.com/images/4KHjFzzCe4x4HCsHdmyP18pI0.jpg 1280w`,style:{aspectRatio:`1280 / 854`},width:`640`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`Let me be clear: being present and available when needed is important in our collaborative roles. That said, there are no strict rules about work hours. You don’t need my permission to be out for a doctor’s appointment. We’re all adults, and I trust your judgment. Just balance your priorities, and if you’ll be unavailable for a while, let the right people know.`}),r(`h4`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Presence`}),r(`p`,{children:`To me, a meeting means a clear purpose, the right people, and someone driving it toward a goal. I aim to be on time, though back-to-backs can make it tricky—I’ll usually be there within the first five minutes. In fact, I start all my meetings 5 minutes past to give us all time in between.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`I value presence and focus in meetings. If you’re distracted or multitasking—like going dark in a virtual meeting or staying glued to your laptop—it doesn’t sit well with me. If it happens often, I’ll call it out. If something urgent comes up, let me know and step out. Otherwise, I expect you to give your full attention, as we all should for each other.`}),r(`h4`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Healthy Work/Life Balance`}),r(`p`,{children:`I do my best to practice a healthy work/life balance by disconnecting from work at night and on weekends. While I occasionally work on weekends, it’s by choice—not expectation. If you get an email from me outside your work hours, it’s not urgent unless I explicitly say so. I encourage you to establish healthy boundaries, take time off, and disconnect, too—it’s when some of the best ideas happen.`}),r(`h3`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`My Guiding Principles`}),r(`img`,{alt:`Various mapping tools, compasses`,className:`framer-image`,height:`427`,src:`https://framerusercontent.com/images/roh5CDrMKJcMP5bEW5ccPX9B6pM.jpg`,srcSet:`https://framerusercontent.com/images/roh5CDrMKJcMP5bEW5ccPX9B6pM.jpg?scale-down-to=512 512w,https://framerusercontent.com/images/roh5CDrMKJcMP5bEW5ccPX9B6pM.jpg?scale-down-to=1024 1024w,https://framerusercontent.com/images/roh5CDrMKJcMP5bEW5ccPX9B6pM.jpg 1280w`,style:{aspectRatio:`1280 / 854`},width:`640`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`People First`}),`\xA0`]}),r(`p`,{children:`Happy, informed, and diverse teams do great work. I prioritize building teams that are productive and balanced with diverse perspectives because those perspectives improve our ideas and outcomes.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:r(`strong`,{children:`Treat Everyone Fairly\xA0`})}),r(`p`,{children:`I work to understand and address biases to ensure fairness for everyone. If you ever feel mistreated or misrepresented, please tell me so we can address it together.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`Leadership from Everywhere\xA0`}),`\xA0`]}),r(`p`,{children:`Leadership isn’t limited to managers. I look for ways to empower everyone on the team to lead, no matter their role.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`Using Tools with Purpose\xA0`}),`\xA0`]}),r(`p`,{children:`Good tools and processes improve efficiency, effectiveness, and craft. But they’re just that—tools. I value how people use them thoughtfully. If something’s not working, I’ll raise it and work with you to fix it.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`Learn from Mistakes\xA0`}),`\xA0`]}),r(`p`,{children:`Mistakes are opportunities to learn. I focus on understanding why something happened and how we can do better next time. Repeated mistakes are what we aim to avoid.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`Little Things Matter\xA0`}),`\xA0`]}),r(`p`,{children:`Attention to detail counts—whether fixing bugs or choosing the right words in a design. If something’s off, speak up or take action. I believe small fixes can have a big impact. I care deeply about the words and formatting in our designs—they matter, especially when they reach millions of people. Getting them right is essential. On the flip side, I’m less concerned about perfect wording in chats. What matters there is intent, trust, and open communication.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:r(`strong`,{children:`Assume Positive Intent\xA0`})}),r(`p`,{children:`I try to approach every situation with an open mind, assuming good intentions. If something feels off, let’s discuss it—I’m always open to more context or feedback so we can move forward together.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Quirks and Errata`}),r(`img`,{alt:`Pug wrapped in a blanket on a bed`,className:`framer-image`,height:`426`,src:`https://framerusercontent.com/images/wyp67KoA5T5TibS0s1pz6xGY.jpg`,srcSet:`https://framerusercontent.com/images/wyp67KoA5T5TibS0s1pz6xGY.jpg?scale-down-to=512 512w,https://framerusercontent.com/images/wyp67KoA5T5TibS0s1pz6xGY.jpg?scale-down-to=1024 1024w,https://framerusercontent.com/images/wyp67KoA5T5TibS0s1pz6xGY.jpg 1279w`,style:{aspectRatio:`1279 / 853`},width:`639`}),a(`p`,{children:[r(`br`,{}),r(`br`,{className:`trailing-break`})]}),a(`p`,{children:[`Here’s a bit more about me—quirks included. While this document is about my style and expectations, I’m equally curious about how\xA0`,r(`em`,{children:`you\xA0`}),`work best. Let’s think of this as the start of an ongoing conversation.`]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`Leadership Style`}),`\xA0`]}),r(`p`,{children:`I aim to inspire and give you the autonomy to own your work. Think like an owner, but know I’m always available to help, advise, or support you. I’m compassionate, laid-back, and soft-spoken at times, but I’m also engaged, opinionated, and passionate about our work.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:r(`strong`,{children:`Deep Focus`})}),r(`p`,{children:`I love context before forming strong opinions. I often focus on small details, like copy or presentation fonts, even when they seem secondary to the big picture. Inclusive design, accessibility, and branding matter to me, so I’ll often dive deep into these areas with you.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:r(`strong`,{children:`Communication Style`})}),r(`p`,{children:`I try to stay on top of email, Slack, and other messages, but sometimes things slip through. Clear, concise messages with bullet points help me prioritize. Long, tangled threads aren’t my thing, so keep it brief if you need my attention. Also, I’m not a fan of corporate speak or using verbs as nouns (though I think I’ve lost that battle).`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`Continuous Improvement`}),`\xA0`]}),r(`p`,{children:`I’m always looking for ways to improve our processes and meetings. If something isn’t working, let’s change it. Feel free to pitch new ideas—change is welcome.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:r(`strong`,{children:`Feedback is a Gift\xA0`})}),r(`p`,{children:`I believe in open, honest, and constructive feedback. It builds trust and respect. I’ll give direct feedback and expect the same from you.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:r(`strong`,{children:`Peeves and Dislikes`})}),r(`p`,{children:`I get annoyed by gossip, rumor-mongering, people stating opinions as facts, and comparisons like, “Company X does it this way, so we should too.” As for dislikes: cilantro, goat cheese, and corduroy. (That’s a story for another time.)`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[r(`strong`,{children:`Let’s Have Fun`}),`\xA0`]}),r(`p`,{children:`I’m a big believer in humor and having some fun. Humor helps build strong connections. My sense of humor is dry, witty, and sometimes silly. I also enjoy geeking out about creative tools, tech, design, movies, books, or anything that interests us. I believe in making time to connect, so I prioritize team offsites every few months to switch off and bond.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`——————`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Steal This Document`}),a(`p`,{children:[`This document is a work in progress, updated regularly. I’ve borrowed ideas from inspiring leaders like\xA0`,r(l,{href:`https://www.linkedin.com/in/michaellopp/`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`Michael Lopp`})}),`,\xA0`,r(l,{href:`https://www.linkedin.com/in/julie-zhuo/`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`Julie Zhuo`})}),`, and\xA0`,r(l,{href:`https://www.linkedin.com/in/augustdlr/`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`August de Los Reyes`})}),`. August encouraged me to steal his version of this document, and now I encourage you to do the same.`]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`Thanks for reading to the end. Let me know your thoughts—this is a conversation, not a monologue. So what’s in your readme?`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[`This post can also be found on\xA0`,r(l,{href:`https://gpenston.medium.com/my-readme-2022-bba1b9bbe3c5`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`Medium`})}),`\xA0and\xA0`,r(l,{href:`https://www.linkedin.com/pulse/my-readme-2022-george-penston/`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`LinkedIn`})}),`.`]})]}),m=a(n,{children:[r(`h3`,{children:`Introduction`}),a(`p`,{children:[`Building on our\xA0`,r(l,{href:`https://www.linkedin.com/pulse/how-our-new-look-embodies-linkedins-warm-welcoming-community-joann-wu/?trackingId=VGv%2B01%2BUQnOx49kPql8g4g%3D%3D`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`design refresh`})}),`, which aimed to bring to life our diverse, warm and welcoming community, LinkedIn’s Design, Product, and Development teams came together over the past year to bring Dark Mode to our 800M members around the globe.`]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`We took a thoughtful approach to the overall Dark Mode user experience, particularly accessibility considerations, to ensure all members can be productive and successful on our platform regardless of their abilities. Members want to stay informed, engage in an active community, and find their next opportunity irrespective of day or night. In addition, we wanted to meet members in their environment and reduce anxiety by providing a UI that adapts.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Accessible and Inclusive from the Start`}),r(`p`,{children:`We ensured that our Dark Mode theme met accessibility standards by checking and adjusting all text and UI elements for their color and contrast to help reduce eye strain and those with light sensitivities, yet still easy to read.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`We also focused on best accommodating the overall light to dark background contrast while staying mindful of how they may layer or interact with other elements. The Dark Mode design also builds upon our existing accessibility features, such as text scaling, device orientation and page reflow, and appropriately sized tap targets.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`It’s All About Semantics`}),a(`p`,{children:[`Once the design system Dark Mode theme was complete, we devised the design token system to support it.\xA0Design tokens are semantic labels or variables to a color or a set of style values.\xA0So instead of saying something is red (or\xA0`,r(`code`,{children:`#FF0000`}),`), we may define it as something like “`,r(`code`,{children:`signal-color-error`}),`” so that we have the flexibility to change the underlying values down the road along with what we selected in Dark Mode. So if we decide to change our “`,r(`code`,{children:`signal-color-error`}),`” from a safety red to a burnt orange color, we can easily make this change once and have it reflected throughout the system. Design tokens also pave the way to produce other themes later on.`]}),r(`img`,{alt:`Diagram showing how a color value relates to a token`,className:`framer-image`,height:`294`,src:`https://framerusercontent.com/images/LgAvVnEN2IIz2BMx7X4uMck0s0.png`,srcSet:`https://framerusercontent.com/images/LgAvVnEN2IIz2BMx7X4uMck0s0.png?scale-down-to=512 512w,https://framerusercontent.com/images/LgAvVnEN2IIz2BMx7X4uMck0s0.png 960w`,style:{aspectRatio:`960 / 589`},width:`480`}),r(`p`,{children:r(`em`,{children:`A color value or variable doesn’t convey how the color should be applied whereas a semantic design token does.`})}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`Within LinkedIn, we have many discrete teams who design and build for our consumer apps, and we\xA0had to devise a plan to coordinate across all of them to roll this out consistently and holistically.\xA0We coordinated and ran sprints across the working teams and semantically updated over 10,000 color usages to deliver a cohesive Dark Mode experience across the consumer product. Along with this, our engineering team incorporated tools in the code to look for any non-design token values in order to maintain good hygiene in the future.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Illustrating for Darkness`}),r(`p`,{children:`We also took this opportunity to introduce Dark Mode versions of our illustrations that complement the Dark Mode experience. These illustrations capture a wide variety of industries and fields beyond tech and represent professionals of all abilities and backgrounds, bringing our vibrant and diverse LinkedIn community to life. Our design systems team is consistently revisiting these and creating new illustrations representing inclusion, equity, and remote work, along with Dark Mode variations.\xA0There’s even a couple of fun easter eggs, such as showing the moon vs. the sun.\xA0The underlying infrastructure takes care of swapping out the illustrations.`}),r(`img`,{alt:`Animation showing illustration going from light to dark`,className:`framer-image`,height:`174`,src:`https://framerusercontent.com/images/ofOnqtQSMCPnwgTGjPGtzJ5fI.gif`,srcSet:`https://framerusercontent.com/images/ofOnqtQSMCPnwgTGjPGtzJ5fI.gif?scale-down-to=512 512w,https://framerusercontent.com/images/ofOnqtQSMCPnwgTGjPGtzJ5fI.gif 835w`,style:{aspectRatio:`835 / 348`},width:`417`}),r(`p`,{children:r(`em`,{children:`Our product illustrations now have Dark Mode-friendly versions.`})}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Onward With Dark Mode`}),r(`p`,{children:`Our Design organization migrated over to Figma a couple of years ago. Figma is a cloud-based design tool that has been invaluable for our teams to collaborate while working virtually. Figma allows our teams to constantly be in sync with the latest updates to our design system and shared design patterns, regardless of where we are in the world or what time it is. This connectedness helps us continuously keep our design tokens updated as we continue to enhance the Dark Mode experience for our members.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`We’ve also developed our own Figma plugins to help the team select inclusive personas, consider different language word lengths, spec’ing for accessibility, and now preview their designs for Dark Mode. This new Figma plugin allows designers to focus on designing in light mode and then easily toggle over to preview it in Dark Mode.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`These investments in the tools our designers use every day help keep the team focused on building the best experiences for our members.`}),r(`img`,{alt:`Animation showing app going from light to dark mode`,className:`framer-image`,height:`882`,src:`https://framerusercontent.com/images/jGxd4xcA4GIUlVMqI9r4K9ybeL0.gif`,srcSet:`https://framerusercontent.com/images/jGxd4xcA4GIUlVMqI9r4K9ybeL0.gif?scale-down-to=1024 517w,https://framerusercontent.com/images/jGxd4xcA4GIUlVMqI9r4K9ybeL0.gif 892w`,style:{aspectRatio:`892 / 1764`},width:`446`}),r(`p`,{children:r(`em`,{children:`Experience Dark Mode throughout the app whether you prefer it at certain times of the day or all the time.`})}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Available on a Screen Near You`}),r(`p`,{children:`We’re excited to announce that we’ve fully rolled out Dark Mode on mobile to our members across the globe.\xA0In addition, desktop web support will be made available to everyone in the next month.`}),r(`img`,{alt:`Screenshots of where to find the dark mode settings.`,className:`framer-image`,height:`361`,src:`https://framerusercontent.com/images/g27UF82QjxdWEOBWIec2DU2ZP4.png`,srcSet:`https://framerusercontent.com/images/g27UF82QjxdWEOBWIec2DU2ZP4.png?scale-down-to=512 512w,https://framerusercontent.com/images/g27UF82QjxdWEOBWIec2DU2ZP4.png?scale-down-to=1024 1024w,https://framerusercontent.com/images/g27UF82QjxdWEOBWIec2DU2ZP4.png 1400w`,style:{aspectRatio:`1400 / 723`},width:`700`}),r(`p`,{children:r(`em`,{children:`Dark Mode is now available for mobile. You can enable it from your mobile app’s settings.`})}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[`To enable Dark Mode on your mobile device, first, ensure your app is up to date. Next, head into the app’s settings by tapping your profile picture in the upper-left corner of the screen, then choose\xA0`,r(`em`,{children:`Settings`}),`\xA0in the header section. Then in Settings, choose\xA0`,r(`em`,{children:`Account preferences`}),`\xA0>\xA0`,r(`em`,{children:`Display / Dark mode`}),`. From this Dark mode settings screen, you can then choose to inherit your operating system’s (Android / iOS) dark mode display settings or have dark mode always on (or light mode always on) within your LinkedIn app.I’m thrilled to have been a part of making this much-requested feature a reality for our members and want to thank everyone that helped Dark Mode come to light. We hope you all are just as excited to start using it.`]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[`If you’d like to work on initiatives such as this and bring valuable features to our members and customers, join us! Our Design team is hiring.\xA0`,r(l,{href:`https://design.linkedin.com/we-re-hiring`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`design.linkedin.com`})})]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`I want to thank the many of those in Design, Engineering, and Product that helped in this initiative. This project was undoubtedly a team effort spanning multiple teams. Thank you to everyone that helped and contributed to Dark Mode!`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[`This post was also published on `,r(l,{href:`https://gpenston.medium.com/introducing-dark-mode-to-linkedin-1f5dd985b1a7`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`Medium`})}),` and `,r(l,{href:`https://www.linkedin.com/pulse/introducing-dark-mode-linkedina-night-day-difference-george-penston/`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`LinkedIn`})}),`.`]})]}),h=a(n,{children:[r(`blockquote`,{children:r(`h3`,{children:`“Wouldn’t it be cool if we had this? Oh, yeah, and that, we gotta have the latest in that other thing.”`})}),a(`p`,{children:[r(`br`,{}),`Next thing you know, the charming idea of adding features has turned your product into a monstrosity. So here are some tools I find to help slay the feature creep before it eats your product alive.`]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`Feature creep is probably one of the most fundamental challenges for product designers and product managers to contend with. It’s easy as you develop a product to get personally invested in what you believe is the right feature set for a product to successfully be released. Unless you’re part Vulcan, we can’t help but get emotionally attached to what we believe will make or break a feature or product introduction.`}),r(`p`,{children:`I believe there are a handful of tools at our disposal to help counter feature creep:`}),r(`ul`,{children:r(`li`,{"data-preset-tag":`p`,children:r(`p`,{children:`Personas `})})}),r(`ul`,{children:r(`li`,{"data-preset-tag":`p`,children:r(`p`,{children:`Agile development`})})}),r(`ul`,{children:r(`li`,{"data-preset-tag":`p`,children:r(`p`,{children:`Usage metrics—both qualitative and quantitative`})})}),r(`blockquote`,{children:r(`h4`,{children:`“A persona is like a stage actor who understands the motivations of their character and can then express them.”`})}),r(`h3`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Personas`}),a(`p`,{children:[r(l,{href:`https://twitter.com/MrAlanCooper`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`Alan Cooper`})}),`, the inventor of design personas, describes them as “A persona is like a stage actor who understands their character’s motivations and can then express them.” Making the most out of personas is a great first line of defense to keep the feature creep at bay. Understanding a user’s motivation when working with your product or feature will help guide you and the team on what needs to be included and what doesn’t.`]}),r(`div`,{className:`framer-text-module`,style:{"--aspect-ratio":`560 / 315`,aspectRatio:`560 / 315`,height:`auto`,width:`100%`},children:r(u,{componentIdentifier:`module:NEd4VmDdsxM3StIUbddO/1de6WpgIbCrKkRcPfQcW/YouTube.js:Youtube`,children:e=>r(f,{...e,play:`Off`,shouldMute:!0,thumbnail:`Medium Quality`,url:`https://www.youtube.com/watch?v=G7ljzXB40hw&embeds_widget_referrer=https%3A%2F%2Fgpenston.medium.com%2F&embeds_referring_euri=https%3A%2F%2Fcdn.embedly.com%2F&embeds_referring_origin=https%3A%2F%2Fcdn.embedly.com&source_ve_path=MjM4NTE`})})}),r(`p`,{children:r(`em`,{children:`Interaction design luminary Alan Cooper discusses the importance of using personas in designing interfaces.`})}),r(`h3`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Agile Development`}),a(`p`,{children:[`Something teams I’ve worked with have invested in is really embracing the notion of agile development. While I realize it can be challenging to consider moving to agile development if you’re releasing at more extended periods, I can’t tell you how much developing and having weekly releases has changed our mindset on product development. While there’s an art of knowing what the\xA0`,r(l,{href:`https://mailchimp.com/resources/minimum-viable-product/`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`minimal viable product (MVP)`})}),`\xA0and\xA0`,r(l,{href:`http://andrewchen.co/minimum-desirable-product/`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!0,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`minimal desirable product (MDP)`})}),`\xA0is to go out with, I do think having a weekly sprint provides a comfort level to what these terms are. I can’t stress this enough, get the features out there in the hands of your users and measure and learn what is working for them and what isn’t. Feature creep to me is usually a select set of customers or your internal team speculating what is crucial for a product — not real-life users and customers giving you honest feedback.`]}),r(`h3`,{children:r(`br`,{className:`trailing-break`})}),r(`h3`,{children:`Usage Metrics`}),r(`p`,{children:`And to complete the circle of life, once you get your MVP out to your users, you have to measure it to see where it’s hitting all the right notes and where it’s failing to meet expectations. Usage metrics are helpful to inform what features you set out to build out next. Qualitative metrics just means to get out of the building and meet with your users. Learn what’s working for them and what’s not. You can then back this up with quantitative metrics. Quantitative just means that you’ve added in analytics into your feature set to see if the data points line up with what the users are telling you. If you’re releasing weekly or in an agile manner, you can quickly bring back the learnings from your users to the product team and make small but carefully measured iterations. What’s great about all this is the team feels really good about the learnings and know they’re building a product users are actually using and finding value.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`By using these processes and tools, you remove the emotional components to shine a light on the actual features your users really can make use of. The guesswork and debates of whether a features needs to get into the product right away slides by the wayside as real data aids in making the best possible product prevail.`})]}),g=a(n,{children:[a(`p`,{children:[`Most likely, in just a couple of days, iOS 7’s release date will be announced. I have mixed feeling about the design direction of iOS 7 for much of what I describe as a\xA0`,r(l,{href:`https://medium.com/@h_locke/affordances-and-signifiers-82bd6f50fc1a`,motionChild:!0,nodeId:`WTXlV9g7E`,openInNewTab:!1,relValues:[],scopeId:`contentManagement`,smoothScroll:!1,children:r(o.a,{children:`lack of affordance`})}),`\xA0(more on this later). The other big concern is the icons aren’t consistently helpful either. They’re not consistent and not all great, and they aren’t consistently great. But you have to admit it’s a bold new direction for Apple, and while some will say Apple is arriving late to the party, as usual, others will say it’s about fashion (which a bunch of it is). So it’s hard to argue that it won’t be new and different. And I bet in a few months; we will wonder how the hell we even got along with the old look of iOS.`]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),a(`p`,{children:[`So Apple is joining the party that Google and Microsoft have been in for over the past year. What’s new with Apple arriving late to the scene with fresh takes on old ideas? We’ve seen this play out time and time again. Many people get infuriated by this, and others see it as Apple’s innate way to take their time and disrupt things on their terms. Windows Phone and Window 8 have\xA0`,r(`em`,{children:`some`}),`\xA0new/good design thinking. You could argue it really pushed Apple to consider their design approach sooner for where iOS 7 was going. But I condemn both Microsoft and Apple for going too far and throwing affordance out the window. I know we’re all tired of glossy, button-y buttons, but give us something to distinguish between labels, text, and tappable buttons. User experiences can be clean, fresh, and minimal while being obvious and inviting.`,r(`em`,{children:`\xA0`}),`Just a thin round rectangle around the label would be perfectly acceptable. Apple is doing this in some small areas like iTunes Radio to buy a song, but their early guidelines for iOS 7 direct developers and designers to just use text. This guidance is just ridiculous. I hope with follow-up releases, they see the error of their ways and bring back some discreet level of affordance.`]}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`blockquote`,{children:r(`p`,{children:`User experiences can be clean, fresh, and minimal while being obvious and inviting.`})}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`I had the opportunity to try out a Microsoft Surface. The experience simply isn’t good. I grew frustrated with it in under a minute as I attempted to log in and open the browser. Again, no affordance and hiding everything as learned gestures makes for a very frustrated user. It seems as though everyone is really swinging the pendulum way too far the other way. I’m hoping it’ll even out sooner or later. Either Apple, Google, and Microsoft will figure this out and remedy the situation, or we will all learn to live with it and tap any bit of text that we think is tappable.`}),r(`p`,{children:r(`br`,{className:`trailing-break`})}),r(`p`,{children:`So what’s up with OS X then? Well, rumor has it Mac OS X Mavericks (10.9) will ship this October. It has slight hints of the design direction of iOS 7. Things like new apps (iBooks, Maps) have simplified, cleaner icon designs and older apps that took the skeuomorphism thing too far now have it way dialed back. But I think the team is in this “one thing at a time” mode, and iOS is definitely their crown jewel and design sandbox in many respects. So I think we’ll get along with Mavericks for a year, and then we’ll see a lot of iOS 7 design direction show up in the new release. Let’s just hope Apple has figured out the right amount of affordance by then, which has got to be more than none.`})]}),_={exports:{richText:{type:`variable`,annotations:{framerContractVersion:`1`}},richText2:{type:`variable`,annotations:{framerContractVersion:`1`}},richText3:{type:`variable`,annotations:{framerContractVersion:`1`}},richText1:{type:`variable`,annotations:{framerContractVersion:`1`}},__FramerMetadata__:{type:`variable`}}}}))();export{_ as __FramerMetadata__,p as richText,m as richText1,h as richText2,g as richText3};
//# sourceMappingURL=WTXlV9g7E-2.D8OUnBri.mjs.map